  private readStringArray(value: unknown): string[] | undefined {
    if (Array.isArray(value)) {
      const items = value
        .map((item) =>
          typeof item === 'string' ? item.trim() : String(item || '').trim()
        )
        .filter(Boolean);
      return items.length ? items : undefined;
    }

    if (typeof value === 'string' && value.trim()) {
      return value
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean);
    }

    return undefined;
  }

