  private toStringArray(value: unknown): string[] | undefined {
    if (Array.isArray(value)) {
      const list = value
        .map((item) => String(item).trim())
        .filter(Boolean);
      return list.length ? list : undefined;
    }

    if (typeof value === 'string') {
      const list = value
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean);
      return list.length ? list : undefined;
    }

    return undefined;
  }
}

