import 'reflect-metadata';
import { Response, NextFunction } from 'express';
import { Container } from 'typedi';
import { PharmacyOrderService } from '@/modules/pharmacyOrders/services';
import { AuthRequest } from '@/modules/middleware/auth';
import { MarkOrderPaidRequest, OrderQueryParams, PharmacyRecoveryWorklistQuery } from '@/modules/pharmacyOrders/types';
import { AppError } from '@/modules/common/types';

export class PharmacyOrderController {
  private service: PharmacyOrderService;

  constructor() {
    this.service = Container.get(PharmacyOrderService);
  }

  create = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const result = await this.service.create(
      pharmacyId,
      req.body,
      req.user?._id || '',
      req.user?.userType || 'pharmacy'
    );
    res.status(201).json({ success: true, message: 'Order created', data: result });
  };

  requestCustomerRecovery = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const data = await this.service.requestCustomerRecovery(req.user, req.params.id);
    res.setHeader('Cache-Control', 'private, no-store');
    res.status(200).json({ success: true, data });
  };

  getCustomerRecovery = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const data = await this.service.getCustomerRecovery(req.user, req.params.id);
    res.setHeader('Cache-Control', 'private, no-store');
    res.status(200).json({ success: true, data });
  };

  getRecoveryRequests = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const query: PharmacyRecoveryWorklistQuery = {
      page: req.query.page === undefined ? 1 : Number(req.query.page),
      limit: req.query.limit === undefined ? 20 : Number(req.query.limit),
    };
    const result = await this.service.getRecoveryRequests(req.user?.pharmacyId, query);
    const body = JSON.stringify({
      success: true,
      data: result.data,
      pagination: { page: result.page, limit: result.limit, total: result.total, totalPages: result.totalPages },
    });
    if (Buffer.byteLength(body, 'utf8') >= 64 * 1024) {
      throw new AppError({ status: 503, code: 'PHARMACY_RECOVERY_UNAVAILABLE', message: 'Pharmacy recovery is unavailable' });
    }
    res.setHeader('Cache-Control', 'private, no-store');
    res.status(200).type('application/json').send(body);
  };

  getById = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const result = await this.service.getById(
      req.params.id,
      req.user?.userType === 'pharmacy'
        ? (req.user?.pharmacyId || '')
        : (req.user?._id || ''),
      req.user?.userType || ''
    );
    res.status(200).json({ success: true, data: result });
  };

  getAll = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const q = req.query as Record<string, string | undefined>;
    const isPharmacy = req.user?.userType === 'pharmacy';

    const filter: OrderQueryParams = {
      pharmacyId: isPharmacy ? (req.user?.pharmacyId || '') : q.pharmacyId,
      customerId: q.customerId,
      userId: q.userId,
      buyerPharmacyId: q.buyerPharmacyId,
      viewerPharmacyId: isPharmacy ? (req.user?.pharmacyId || '') : undefined,
      orderType: q.orderType as any,
      orderFor: q.orderFor as 'consultation' | 'diagnostic' | undefined,
      status: q.status as any,
      paymentStatus: q.paymentStatus as any,
    };

    const page = q.page ? parseInt(q.page) : 1;
    const limit = q.limit ? parseInt(q.limit) : 20;

    const result = await this.service.getAll(
      filter,
      page,
      limit,
      req.user?.userType || '',
      req.user?.userType === 'pharmacy'
        ? (req.user?.pharmacyId || '')
        : (req.user?._id || '')
    );
    res.status(200).json({
      success: true,
      data: result.data,
      pagination: { page: result.page, limit, total: result.total, totalPages: result.totalPages },
    });
  };

  update = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const result = await this.service.update(req.params.id, pharmacyId, req.body);
    res.status(200).json({ success: true, message: 'Order updated', data: result });
  };

  updateStatus = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const result = await this.service.updateStatus(req.params.id, pharmacyId, req.body);
    res.status(200).json({ success: true, message: 'Status updated', data: result });
  };

  cancel = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const result = await this.service.updateStatus(req.params.id, pharmacyId, {
      status: 'cancelled',
      notes: req.body?.notes,
    });
    res.status(200).json({ success: true, message: 'Order cancelled', data: result });
  };

  markPaid = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const result = await this.service.markPaid(req.params.id, {
      userType: req.user?.userType || '',
      pharmacyId: req.user?.pharmacyId,
      userId: req.user?._id || '',
      data: req.body as MarkOrderPaidRequest,
    });
    res.status(200).json({ success: true, message: 'Order marked as paid', data: result });
  };
}

import { Schema, model, Model } from 'mongoose';
import { IPharmacyOrder, PHARMACY_RECOVERY_ORDER_LABELS, PHARMACY_RECOVERY_PAYMENT_LABELS } from '@/modules/pharmacyOrders/types';

const batchAllocationSchema = new Schema(
  {
    batchId: { type: Schema.Types.ObjectId as any, required: true },
    batchNumber: { type: String, required: true, trim: true },
    expiryDate: { type: String, required: true, match: /^\d{8}$/ },
    quantity: { type: Number, required: true, min: 1 },
  },
  { _id: false }
);

const orderItemSchema = new Schema(
  {
    medicineId: { type: Schema.Types.ObjectId as any, ref: 'Medicine', required: true },
    medicineName: { type: String, trim: true },
    orderedQty: { type: Number, required: true, min: 1 },
    reservedQty: { type: Number, default: 0, min: 0 },
    billedQty: { type: Number, default: 0, min: 0 },
    freeQty: { type: Number, default: 0, min: 0 },
    unitPrice: { type: Number, required: true, min: 0 },
    discount: { type: Number, default: 0, min: 0 },
    lineTotal: { type: Number, required: true, min: 0 },
    hsnCode: { type: String, trim: true },
    gstPercent: { type: Number, min: 0, max: 100 },
    taxAmount: { type: Number, min: 0 },
    unitPricePaise: { type: Number, min: 0 },
    discountPaise: { type: Number, min: 0 },
    taxPaise: { type: Number, min: 0 },
    lineTotalPaise: { type: Number, min: 0 },
    prescriptionRequired: { type: Boolean, default: false },
    batchAllocations: { type: [batchAllocationSchema], default: [] },
    recurring: { type: Boolean, default: false },
    subscriptionFrequency: { type: String, trim: true },
    subscriptionIntervalDays: { type: Number, min: 1 },
    subscriptionNextRefillDate: { type: String, match: /^\d{8}$/ },
    subscriptionReminderChannel: {
      type: String,
      enum: ['sms', 'push', 'both', 'none'],
    },
    itemStatus: {
      type: String,
      enum: ['active', 'replaced', 'removed'],
      default: 'active',
    },
  },
  { _id: false }
);

const sideEffectStateSchema = new Schema(
  {
    status: {
      type: String,
      enum: ['pending', 'success', 'failed'],
      required: true,
    },
    lastError: { type: String, trim: true },
    updatedAt: { type: Date },
  },
  { _id: false }
);

const recoveryObservationSchema = new Schema(
  {
    orderStatusLabel: { type: String, required: true, enum: [...PHARMACY_RECOVERY_ORDER_LABELS] },
    paymentStatusLabel: { type: String, required: true, enum: [...PHARMACY_RECOVERY_PAYMENT_LABELS] },
    paymentRecordId: { type: String, default: null, validate: (value: unknown) => value === null || (typeof value === 'string' && /^[0-9a-f]{24}$/.test(value)) },
    paymentRecordReferenceState: { type: String, required: true, enum: ['recorded', 'missing', 'malformed'] },
  },
  { _id: false, strict: 'throw' }
);

const recoveryRequestSchema = new Schema(
  {
    schemaVersion: { type: Number, required: true, enum: [1] },
    operationKind: { type: String, required: true, enum: ['customer_recovery_request'] },
    operationId: { type: String, required: true },
    requestingCustomerId: { type: String, required: true, match: /^[0-9a-f]{24}$/ },
    orderId: { type: String, required: true, match: /^[0-9a-f]{24}$/ },
    status: { type: String, required: true, enum: ['reconciliation_required'] },
    requestedAt: { type: Date, required: true },
    observation: { type: recoveryObservationSchema, required: true },
    amountMinor: { type: Number, default: null, validate: (value: unknown) => value === null },
    currency: { type: String, default: null, validate: (value: unknown) => value === null },
    instrument: { type: String, required: true, enum: ['unknown'] },
    destinationPolicy: { type: String, required: true, enum: ['original_instrument'] },
    payloadSha256: { type: String, required: true, match: /^[0-9a-f]{64}$/ },
    observationSha256: { type: String, required: true, match: /^[0-9a-f]{64}$/ },
  },
  { _id: false, strict: 'throw' }
);

const pharmacyOrderSchema = new Schema<IPharmacyOrder>(
  {
    orderNumber: { type: String, trim: true, sparse: true, index: true },
    pharmacyId: { type: Schema.Types.ObjectId as any, ref: 'Pharmacy', required: true, index: true },
    orderType: {
      type: String,
      enum: ['in_store', 'online'],
      required: true,
      index: true,
    },
    status: {
      type: String,
      enum: [
        'placed', 'accepted', 'packed',
        'ready_for_pickup', 'out_for_delivery',
        'completed', 'abandoned', 'cancelled', 'rejected',
      ],
      default: 'placed',
      index: true,
    },
    customerId: { type: Schema.Types.ObjectId as any, ref: 'User', index: true },
    buyerPharmacyId: { type: Schema.Types.ObjectId as any, ref: 'Pharmacy', index: true },
    createdById: { type: Schema.Types.ObjectId as any, required: true },
    createdByRole: { type: String, required: true, trim: true },
    items: { type: [orderItemSchema], default: [] },
    subtotal: { type: Number, min: 0 },
    discountTotal: { type: Number, min: 0, default: 0 },
    taxTotal: { type: Number, min: 0, default: 0 },
    grandTotal: { type: Number, min: 0 },
    subtotalPaise: { type: Number, min: 0 },
    discountTotalPaise: { type: Number, min: 0 },
    taxTotalPaise: { type: Number, min: 0 },
    grandTotalPaise: { type: Number, min: 0 },
