import { Types } from 'mongoose';

export const SUPPLIER_FIELDS = ['displayName', 'contactName', 'phone', 'email', 'address'] as const;
export const SUPPLIER_TEXT_LIMITS = { displayName: 120, contactName: 120, phone: 32, email: 254, address: 500 } as const;
export type SupplierState = 'active' | 'archived';
export interface SupplierFields {
  displayName: string;
  contactName: string | null;
  phone: string | null;
  email: string | null;
  address: string | null;
}
export interface IPharmacySupplier extends SupplierFields {
  _id: Types.ObjectId;
  schemaVersion: 1;
  pharmacyId: Types.ObjectId;
  state: SupplierState;
  revision: number;
  createdByActorId: string;
  updatedByActorId: string;
  createdAt: Date;
  updatedAt: Date;
  archivedAt: Date | null;
}
export interface SupplierDto extends SupplierFields {
  supplierId: string;
  state: SupplierState;
  revision: number;
  createdAt: string;
  updatedAt: string;
  archivedAt: string | null;
  verificationState: 'not_evaluated';
}
export interface SupplierListQuery {
  state: SupplierState | 'all';
  page: number;
  limit: number;
}
export interface SupplierPage extends SupplierListQuery {
  data: SupplierDto[];
  total: number;
  totalPages: number;
}
export type SupplierCommand =
  | { kind: 'create'; fields: SupplierFields }
  | { kind: 'update'; fields: Partial<SupplierFields>; expectedRevision: number }
  | { kind: 'archive'; expectedRevision: number };

import Joi from 'joi';
import { AppError } from '@/modules/common/types';
import { SUPPLIER_FIELDS, SUPPLIER_TEXT_LIMITS, SupplierCommand, SupplierFields, SupplierListQuery } from '@/modules/pharmacySuppliers/types';

export const supplierUnavailable = () => new AppError({
  status: 503, code: 'SUPPLIER_MASTER_UNAVAILABLE', message: 'Supplier master is unavailable',
});
export const supplierConflict = () => new AppError({ status: 409, code: 'SUPPLIER_CONFLICT', message: 'Supplier changed' });
const invalidRequest = () => new AppError({ status: 400, code: 'VALIDATION_ERROR', message: 'Invalid supplier request' });
const invalidQuery = () => new AppError({ status: 400, code: 'VALIDATION_ERROR', message: 'Invalid supplier query' });
export const isSupplierId = (value: unknown): value is string => typeof value === 'string' && /^[0-9a-f]{24}$/.test(value);
export function assertSupplierScope(value: unknown): asserts value is string {
  if (!isSupplierId(value)) throw new AppError({ status: 403, code: 'FORBIDDEN', message: 'Access denied' });
}
export function assertSupplierId(value: unknown): asserts value is string {
  if (!isSupplierId(value)) throw new AppError({ status: 400, code: 'VALIDATION_ERROR', message: 'Invalid supplier ID' });
}
export function assertSupplierBody(value: unknown): asserts value is Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value) ||
    ![Object.prototype, null].includes(Object.getPrototypeOf(value))) throw invalidRequest();
}
const fieldsSchema = Joi.object({
  displayName: Joi.string().trim().min(1).max(SUPPLIER_TEXT_LIMITS.displayName).required(),
  contactName: Joi.string().trim().min(1).max(SUPPLIER_TEXT_LIMITS.contactName).allow(null).required(),
  phone: Joi.string().trim().min(1).max(SUPPLIER_TEXT_LIMITS.phone).pattern(/^[+0-9(). -]+$/).allow(null).required(),
  email: Joi.string().trim().email({ tlds: { allow: false } }).max(SUPPLIER_TEXT_LIMITS.email).allow(null).required(),
  address: Joi.string().trim().min(1).max(SUPPLIER_TEXT_LIMITS.address).allow(null).required(),
}).unknown(false);
const patchSchema = fieldsSchema.fork([...SUPPLIER_FIELDS], field => field.optional()).min(1);
const options = { convert: false, stripUnknown: false, abortEarly: false };
export function validStoredSupplierFields(value: unknown): value is SupplierFields {
  return !fieldsSchema.validate(value, options).error;
}
export function normalizeSupplierCommand(kind: 'create', body: Record<string, unknown>): Extract<SupplierCommand, { kind: 'create' }>;
export function normalizeSupplierCommand(kind: 'update', body: Record<string, unknown>): Extract<SupplierCommand, { kind: 'update' }>;
export function normalizeSupplierCommand(kind: 'archive', body: Record<string, unknown>): Extract<SupplierCommand, { kind: 'archive' }>;
export function normalizeSupplierCommand(kind: SupplierCommand['kind'], body: Record<string, unknown>): SupplierCommand {
  const allowed: readonly string[] = kind === 'create' ? SUPPLIER_FIELDS
    : kind === 'update' ? [...SUPPLIER_FIELDS, 'expectedRevision'] : ['expectedRevision'];
  const keys = Reflect.ownKeys(body);
  if (keys.some(key => typeof key !== 'string' || !allowed.includes(key))) {
    throw new AppError({ status: 422, code: 'FORBIDDEN_FIELD', message: 'One or more fields cannot be changed through this endpoint' });
  }
  for (const key of keys) {
    const descriptor = Object.getOwnPropertyDescriptor(body, key)!;
    if (!descriptor.enumerable || !('value' in descriptor)) throw invalidRequest();
  }
  for (const key of keys) {
    if (Object.getOwnPropertyDescriptor(body, key)!.value === undefined) throw invalidRequest();
  }
  const fields: Record<string, unknown> = {};
  if (kind !== 'archive') {
    for (const key of SUPPLIER_FIELDS) {
      const descriptor = Object.getOwnPropertyDescriptor(body, key);
      if (!descriptor && kind === 'update') continue;
      if (!descriptor) { fields[key] = key === 'displayName' ? undefined : null; continue; }
      const value = descriptor.value;
      if (value === null) fields[key] = null;
      else if (typeof value === 'string') {
        const normalized = value.trim();
        fields[key] = key !== 'displayName' && normalized.length === 0 ? null : normalized;
      } else throw invalidRequest();
    }
    if ((kind === 'create' ? fieldsSchema : patchSchema).validate(fields, options).error) throw invalidRequest();
  }
  if (kind === 'create') return { kind, fields: fields as unknown as SupplierFields };
  const expectedRevision = Object.getOwnPropertyDescriptor(body, 'expectedRevision')?.value;
  if (typeof expectedRevision !== 'number' || !Number.isSafeInteger(expectedRevision) ||
    expectedRevision < 1 || expectedRevision >= Number.MAX_SAFE_INTEGER) throw invalidRequest();
  return kind === 'archive' ? { kind, expectedRevision } : { kind, fields: fields as Partial<SupplierFields>, expectedRevision };
}
export const supplierListQuerySchema = Joi.object({
  state: Joi.string().valid('active', 'archived', 'all').optional(),
  page: Joi.number().integer().min(1).max(1000).optional(),
  limit: Joi.number().integer().min(1).max(50).optional(),
  pharmacyId: Joi.forbidden(),
});
export function normalizeSupplierQuery(value: unknown): SupplierListQuery {
  if (!value || typeof value !== 'object' || Array.isArray(value) ||
    ![Object.prototype, null].includes(Object.getPrototypeOf(value))) throw invalidQuery();
  for (const key of Reflect.ownKeys(value)) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key)!;
    if (typeof key !== 'string' || !['state', 'page', 'limit'].includes(key) ||
      !descriptor.enumerable || !('value' in descriptor)) throw invalidQuery();
  }
  const state = Object.getOwnPropertyDescriptor(value, 'state')?.value;
  const page = Object.getOwnPropertyDescriptor(value, 'page')?.value;
  const limit = Object.getOwnPropertyDescriptor(value, 'limit')?.value;
  const query = { state: state === undefined ? 'active' : state, page: page === undefined ? 1 : page, limit: limit === undefined ? 20 : limit };
  if (supplierListQuerySchema.validate(query, options).error) throw invalidQuery();
  return query as SupplierListQuery;
}

import { Service } from 'typedi';
import { AppError } from '@/modules/common/types';
import { SlotService } from '@/modules/slots/services';
import { SlotRepository } from '@/modules/slots/repository';
import { BookingRepository } from '@/modules/bookings/repository';
import { BookingService } from '@/modules/bookings/services';
import { UserRepository } from '@/modules/user/repository';
import { SpecialistService } from '@/modules/specialists/services';
import { NotificationService } from '@/modules/notification/services';
import {
  CreateSlotRequest,
  ISlot,
  UpdateSlotRequest,
} from '@/modules/slots/types';
import {
  IBooking,
  IBookingPrescription,
  IBookingPrescriptionMedicine,
} from '@/modules/bookings/types';
import { IUser } from '@/modules/user/types';
import {
  ISpecialist,
  UpdateSpecialistRequest,
} from '@/modules/specialists/types';
import { CONFIG } from '@/config/config';
import { execFile } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { promisify } from 'util';
import { buildBookingLifecyclePatch } from '@/modules/bookings/utils/lifecycle';

export interface SpecialistAppointmentQuery {
  view: 'day' | 'month' | 'all';
  date?: string;
  yearMonth?: string;
  page?: number;
  limit?: number;
}

export interface SpecialistAppointmentDetails {
  booking: IBooking;
  patient: ReturnType<SpecialistPortalService['toPatientSummary']>;
}

interface CreateAppointmentPrescriptionRequest {
  diagnosis: string;
  medicines?: IBookingPrescriptionMedicine[];
  testsAdvised?: string[];
  advice: string;
  message?: string;
}

@Service()
export class SpecialistPortalService {
  constructor(
    private slotService: SlotService,
    private slotRepository: SlotRepository,
    private bookingRepository: BookingRepository,
    private bookingService: BookingService,
    private userRepository: UserRepository,
    private specialistService: SpecialistService,
    private notificationService: NotificationService
  ) {}

  private readonly execFileAsync = promisify(execFile);

  private buildLifecyclePatch(
    current: IBooking['lifecycle'],
    updates: Parameters<typeof buildBookingLifecyclePatch>[1]
  ) {
    return buildBookingLifecyclePatch(current, updates);
  }

  async getProfile(specialistId: string): Promise<ISpecialist> {
    return this.specialistService.getById(specialistId);
  }

  async updateProfile(
    specialistId: string,
    body: UpdateSpecialistRequest
  ): Promise<ISpecialist> {
    if (
      body !== null &&
      typeof body === 'object' &&
      ['isVerified', 'isActive', 'rating'].some((field) =>
        Object.prototype.hasOwnProperty.call(body, field)
      )
    ) {
      await this.specialistService.getById(specialistId);
      throw new AppError({
        status: 422,
        code: 'FORBIDDEN_FIELD',
        message: 'Specialist profile contains fields that cannot be updated',
      });
    }

    return this.specialistService.update(specialistId, body);
  }

  async createSlot(
    specialistId: string,
    body: Omit<CreateSlotRequest, 'specialistId' | 'wellnessPackageId'>
  ): Promise<ISlot[]> {
    const payload: CreateSlotRequest = {
      ...body,
      specialistId,
    };
    return this.slotService.create(payload);
  }

  async listSlots(specialistId: string, date?: string): Promise<ISlot[]> {
    return this.slotRepository.findManagedBySpecialistId(specialistId, date);
  }

  async updateSlot(
    specialistId: string,
    slotId: string,
    body: UpdateSlotRequest
  ): Promise<ISlot> {
    const slot = await this.slotRepository.findById(slotId);
    if (!slot || String(slot.specialistId) !== String(specialistId)) {
      throw new AppError({
        status: 404,
        code: 'SLOT_NOT_FOUND',
        message: 'Slot not found',
      });
    }
    return this.slotService.update(slotId, body);
  }

  async deleteSlot(specialistId: string, slotId: string): Promise<void> {
    const slot = await this.slotRepository.findById(slotId);
    if (!slot || String(slot.specialistId) !== String(specialistId)) {
      throw new AppError({
        status: 404,
        code: 'SLOT_NOT_FOUND',
        message: 'Slot not found',
      });
    }
    const hasBookings = (slot.currentBookings ?? 0) > 0;
    if (hasBookings) {
      throw new AppError({
        status: 400,
        code: 'SLOT_HAS_BOOKINGS',
        message: 'Cannot delete a slot that has active bookings',
      });
    }
    await this.slotService.delete(slotId);
  }

  async listAppointments(
    specialistId: string,
    query: SpecialistAppointmentQuery
  ): Promise<{
    data: IBooking[];
    total: number;
    page?: number;
    totalPages?: number;
  }> {
    if (query.view === 'day') {
      return this.bookingRepository.findConsultationsForSpecialist(
        specialistId,
        { bookingDate: query.date! }
      );
    }
    if (query.view === 'month') {
      return this.bookingRepository.findConsultationsForSpecialist(
        specialistId,
        { yearMonth: query.yearMonth! }
      );
    }
    const page = query.page ?? 1;
    const limit = query.limit ?? 20;
    return this.bookingRepository.findConsultationsForSpecialist(specialistId, {
      page,
      limit,
    });
  }

  async getAppointmentById(
    specialistId: string,
    bookingId: string
  ): Promise<SpecialistAppointmentDetails> {
    const booking = await this.bookingRepository.findById(bookingId);
    if (
      !booking ||
      booking.bookingType !== 'consultation' ||
      String(booking.specialistId) !== String(specialistId)
    ) {
      throw new AppError({
        status: 404,
        code: 'BOOKING_NOT_FOUND',
        message: 'Booking not found',
      });
    }

    const patient = await this.userRepository.findById(booking.userId);
    if (!patient) {
      throw new AppError({
        status: 404,
        code: 'USER_NOT_FOUND',
        message: 'Patient not found',
      });
    }

    return {
      booking,
      patient: this.toPatientSummary(patient),
    };
  }

  async updateAppointmentStatus(
    specialistId: string,
    bookingId: string,
    status: IBooking['status']
  ): Promise<IBooking> {
    const booking = await this.bookingRepository.findById(bookingId);
    if (
      !booking ||
      booking.bookingType !== 'consultation' ||
      String(booking.specialistId) !== String(specialistId)
    ) {
      throw new AppError({
        status: 404,
        code: 'BOOKING_NOT_FOUND',
        message: 'Booking not found',
      });
    }

    if (booking.status === 'cancelled' && status !== 'cancelled') {
      throw new AppError({
        status: 400,
        code: 'BOOKING_ALREADY_CANCELLED',
        message: 'Cancelled booking status cannot be changed',
      });
    }

    const updated = await this.bookingService.update(bookingId, {
      status,
      cancellationReason:
        status === 'cancelled' ? 'Cancelled by specialist' : undefined,
    });

    if (status === 'cancelled') {
      try {
        await this.notificationService.createSpecialistAppointmentCancelledNotification(
          specialistId,
          bookingId,
          {
            bookingType: booking.bookingType,
            bookingDate: booking.bookingDate,
            bookingTime: booking.bookingTime,
            userId: booking.userId,
          }
        );
      } catch (error) {
        console.error(
          'Failed to create specialist cancellation notification:',
          error
        );
      }
      return updated;
    }

    if (status === 'confirmed') {
      try {
        await this.notificationService.createSpecialistAppointmentConfirmedNotification(
          specialistId,
          bookingId,
          {
            bookingType: booking.bookingType,
            bookingDate: booking.bookingDate,
            bookingTime: booking.bookingTime,
            userId: booking.userId,
          }
        );
      } catch (error) {
        console.error(
          'Failed to create specialist confirmed notification:',
          error
        );
      }
    }

    if (status === 'completed') {
      try {
        await this.notificationService.createSpecialistAppointmentCompletedNotification(
          specialistId,
          bookingId,
          {
            bookingType: booking.bookingType,
            bookingDate: booking.bookingDate,
            bookingTime: booking.bookingTime,
            userId: booking.userId,
          }
        );
      } catch (error) {
        console.error(
          'Failed to create specialist completed notification:',
          error
        );
      }
    }

    return updated;
  }

  async createAppointmentPrescription(
    specialistId: string,
    bookingId: string,
    body: CreateAppointmentPrescriptionRequest
  ): Promise<IBooking> {
    const booking = await this.bookingRepository.findById(bookingId);
    if (
      !booking ||
      booking.bookingType !== 'consultation' ||
      String(booking.specialistId) !== String(specialistId)
    ) {
      throw new AppError({
        status: 404,
        code: 'BOOKING_NOT_FOUND',
        message: 'Booking not found',
      });
    }

    const specialist = await this.specialistService.getById(specialistId);
    const patient = await this.userRepository.findById(booking.userId);
    if (!patient) {
      throw new AppError({
        status: 404,
        code: 'USER_NOT_FOUND',
        message: 'Patient not found',
      });
    }

    const pdfUrl = await this.generatePrescriptionPdf({
      booking,
      patient,
      specialist,
      diagnosis: body.diagnosis,
      medicines: body.medicines || [],
      testsAdvised: body.testsAdvised || [],
      advice: body.advice,
    });

    const prescription: IBookingPrescription = {
      ...(booking.prescription || {}),
      fileUrls: [pdfUrl],
      message: body.message,
      diagnosis: body.diagnosis,
      advice: body.advice,
      medicines: body.medicines || [],
      testsAdvised: body.testsAdvised || [],
      prescribedAt: new Date().toISOString(),
      prescribedBySpecialistId: specialistId,
      prescribedBySpecialistName: specialist.name,
    };

    const updated = await this.bookingRepository.update(
      { _id: bookingId },
      {
        prescription,
        lifecycle: this.buildLifecyclePatch(booking.lifecycle, {
          prescriptionUploaded: true,
        }),
      }
    );
    if (!updated) {
      throw new AppError({
        status: 500,
        code: 'UPDATE_FAILED',
        message: 'Failed to save prescription',
      });
    }

    return updated;
  }

  async getPatientHistory(specialistId: string, patientUserId: string) {
    const bookings =
      await this.bookingRepository.findConsultationsBySpecialistAndUserId(
        specialistId,
        patientUserId
      );

    if (bookings.length === 0) {
      throw new AppError({
        status: 404,
        code: 'PATIENT_HISTORY_NOT_FOUND',
        message: 'No consultations with this patient',
      });
    }

    const user = await this.userRepository.findById(patientUserId);
    if (!user) {
      throw new AppError({
        status: 404,
        code: 'USER_NOT_FOUND',
        message: 'Patient not found',
      });
    }

    const patient = this.toPatientSummary(user);
    const consultations = bookings.map((b) =>
      this.toConsultationSummary(b)
    );

    return { patient, consultations };
  }

  private toPatientSummary(user: IUser) {
    return {
      userId: user._id,
      name: user.name,
      phone: user.phone,
      email: user.email,
      dateOfBirth: user.dateOfBirth,
      gender: user.gender,
      bloodGroup: user.bloodGroup,
      height: user.height,
      weight: user.weight,
      city: user.city,
      state: user.state,
      country: user.country,
      profilePictureUrl: user.profilePictureUrl,
    };
  }

  private toConsultationSummary(b: IBooking) {
    return {
      bookingId: b._id,
      bookingDate: b.bookingDate,
      bookingTime: b.bookingTime,
      status: b.status,
      paymentStatus: b.paymentStatus,
      primaryConcern: b.primaryConcern,
      consultationMode: b.consultationMode,
      serviceMode: b.serviceMode,
      price: b.price,
      notes: b.notes,
      prescription: b.prescription,
      report: b.report,
      documents: b.documents,
      followUp: b.followUp,
      virtualMeeting: b.virtualMeeting,
      dependentId: b.dependentId,
      createdAt: b.createdAt,
      updatedAt: b.updatedAt,
    };
  }

  private async generatePrescriptionPdf(input: {
    booking: IBooking;
    patient: IUser;
    specialist: ISpecialist;
    diagnosis: string;
    medicines: IBookingPrescriptionMedicine[];
    testsAdvised: string[];
    advice: string;
  }): Promise<string> {
    const uploadDir =
      CONFIG.UPLOAD_DIR || path.join(process.cwd(), 'files');
    const bookingId = String(input.booking._id);
    const bookingDir = path.join(uploadDir, 'bookings', bookingId);
    fs.mkdirSync(bookingDir, { recursive: true });

    const timestamp = Date.now();
    const htmlPath = path.join(
      os.tmpdir(),
      `prescription-${bookingId}-${timestamp}.html`
    );
    const pdfFileName = `prescription-${timestamp}.pdf`;
    const pdfPath = path.join(bookingDir, pdfFileName);

    try {
      fs.writeFileSync(htmlPath, this.buildPrescriptionHtml(input), 'utf8');
      await this.execFileAsync(
        process.env.WKHTMLTOPDF_BINARY || 'wkhtmltopdf',
        [htmlPath, pdfPath]
      );
      return `/api/static/bookings/${bookingId}/${pdfFileName}`;
    } catch (error: any) {
      throw new AppError({
        status: 500,
        code: 'PRESCRIPTION_PDF_GENERATION_FAILED',
        message:
          error?.message ||
          'Failed to generate prescription PDF',
      });
    } finally {
      try {
        fs.unlinkSync(htmlPath);
      } catch (_error) {
        // Ignore temp cleanup errors.
      }
    }
  }

  private buildPrescriptionHtml(input: {
    booking: IBooking;
    patient: IUser;
    specialist: ISpecialist;
    diagnosis: string;
    medicines: IBookingPrescriptionMedicine[];
    testsAdvised: string[];
    advice: string;
  }): string {
    const patientName = this.escapeHtml(input.patient.name || 'Patient');
    const specialistName = this.escapeHtml(input.specialist.name || 'Specialist');
    const age = this.calculateAge(input.patient.dateOfBirth);
    const ageText = age !== null ? `Age ${age}` : 'Age N/A';
    const appointmentId = this.escapeHtml(`APT-${String(input.booking._id).slice(-4).toUpperCase()}`);
    const appointmentDate = this.escapeHtml(this.formatDisplayDate(input.booking.bookingDate));
    const diagnosis = this.escapeHtml(input.diagnosis);
    const advice = this.escapeHtml(input.advice).replace(/\n/g, '<br />');

    const medicinesHtml =
      input.medicines.length > 0
        ? input.medicines
            .map((medicine) => {
              const name = this.escapeHtml(medicine.name);
              const details = [
